window.__C=window.__C||{};(__C["inl1"]=__C["inl1"]||[]).push("ey_did\":\"Joined the team that trained ChatGPT (first project: adversarial data collection; human-preference data collection for RLHF); listed author on 'Introducing ChatGPT' (2022) and GPT-4 Technical Report contributor; co-author of 'LLM Critics Help Catch LLM Bugs' (2024); co-first author of IH-Challenge (2026, used to train GPT-5-Mini-R); co-author of GPT-Red (2026, automated red-teamer used to adversarially train GPT-5.6); currently works on reducing ChatGPT's propensity to help make bioweapons, adversarial robustness training and automated red-teaming.\",\"source\":\"https://www.matsprogram.org/mentor/uribe ; https://www.alphaxiv.org/@juan-felipe-ceron-uribe ; https://platzi.com/blog/colombiano-hace-parte-del-equipo-que-entrena-a-chatgpt/ ; https://www.youtube.com/watch?v=-K4tpDB7jxg\"},{\"org\":\"MATS (ML Alignment & Theory Scholars)\",\"role\":\"Mentor, OpenAI Safety Team stream\",\"start\":\"2026\",\"end\":\"present\",\"what_they_did\":\"Mentors scholars on AI control/monitoring, adversarial robustness and safeguards, alignment training methods.\",\"source\":\"https://www.matsprogram.org/mentor/uribe\"}],\"expertise\":[\"adversarial robustness / jailbreak & prompt-injection defense\",\"automated red-teaming (self-play RL)\",\"instruction hierarchy training\",\"biological-misuse safeguards (refusal training, monitors/classifiers)\",\"RLHF and human preference data collection\",\"scalable oversight (LLM critics)\",\"speech-recognition datasets (earlier)\",\"epidemiological modelling (earlier)\"],\"expertise_detail\":\"A hands-on research engineer rather than a theorist: his public record is in the machinery of making deployed frontier models refuse misuse and resist attacks. At OpenAI he moved from RLHF data collection for the original ChatGPT, through scalable-oversight work (LLM critics, with Jan Leike), to Safety Systems work on instruction hierarchy (co-first author of IH-Challenge) and automated red-teaming (GPT-Red), plus bioweapon-misuse mitigations. His citation count (~25\u201335k) is dominated by large team papers (GPT-4 report, ChatGPT blog); his h-index is ~7.\",\"notable_work\":[{\"title\":\"IH-Challenge: A Training Dataset to Improve Instruction Hierarchy on Frontier LLMs (co-first author)\",\"type\":\"paper\",\"year\":2026,\"url\":\"https://arxiv.org/abs/2603.10521\",\"why_it_matters\":\"Released RL dataset; fine-tuning GPT-5-Mini on it raised instruction-hierarchy robustness from 84.1% to 94.1% and cut unsafe behaviour from 6.6% to 0.7%. His most first-hand, safety-specific contribution.\"},{\"title\":\"GPT-Red: Automated Red Teaming via Self-Play at Scale (co-author)\",\"type\":\"paper\",\"year\":2026,\"url\":\"https://arxiv.org/abs/2607.26115\",\"why_it_matters\":\"OpenAI's self-play red-teaming agent used to adversarially train GPT-5.6; described as the largest documented LLM safety training run.\"},{\"title\":\"Introducing ChatGPT / ChatGPT: Optimizing language models for dialogue (listed author)\",\"type\":\"blog\",\"year\":2022,\"url\":\"https://openai.com/index/chatgpt/\",\"why_it_matters\":\"Places him on the original ChatGPT team (RLHF data collection); basis for his 'I started working on what became ChatGPT' claim. (Authorship per Google Scholar listing.)\"},{\"title\":\"GPT-4 Technical Report (contributor)\",\"type\":\"report\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2303.08774\",\"why_it_matters\":\"Contributor on OpenAI's flagship 2023 model; accounts for most of his citations.\"},{\"title\":\"LLM Critics Help Catch LLM Bugs (co-author, 3rd of 6)\",\"type\":\"paper\",\"year\":2024,\"url\":\"https://arxiv.org/abs/2407.00215\",\"why_it_matters\":\"Scalable-oversight work (CriticGPT) with Nat McAleese and Jan Leike's superalignment group: RLHF-trained critics catch more bugs than human contractors.\"},{\"title\":\"The People's Speech: a large-scale diverse English speech recognition dataset for commercial usage\",\"type\":\"paper\",\"year\":2021,\"url\":\"https://arxiv.org/abs/2111.09344\",\"why_it_matters\":\"Pre-OpenAI deep-learning work (MLCommons dataset), ~130 citations.\"},{\"title\":\"Alternative strategies for the estimation of a disease's basic reproduction number: a model-agnostic study\",\"type\":\"paper\",\"year\":2021,\"url\":\"https://scholar.google.com/citations?hl=en&user=X9hMtQgAAAAJ\",\"why_it_matters\":\"Academic epidemiology work from Universidad de los Andes (Bulletin of Mathematical Biology).\"}],\"research_metrics\":{\"google_scholar_url\":\"https://scholar.google.com/citations?hl=en&user=X9hMtQgAAAAJ\",\"citations_approx\":\"~25,000\u201335,000 (Scholar page fetched showed 25,122; a fresher search snapshot showed 33,246; alphaXiv shows 34,557) \u2014 almost entirely from the GPT-4 Technical Report and ChatGPT blog\",\"h_index_approx\":\"6\u20137\",\"as_of\":\"2026-10-18 (values vary by snapshot)\"},\"talks_podcasts\":[{\"title\":\"He works at OpenAI: his job is to stop ChatGPT from helping make a Bioweapon (frominside.ai interview)\",\"show\":\"Palisade Research / From Inside AI (interviewer Eli Tyre)\",\"date\":\"2026-09-29\",\"url\":\"https://www.youtube.com/watch?v=-K4tpDB7jxg\",\"youtube_id_if_any\":\"-K4tpDB7jxg\",\"duration_if_known\":\"33:18 (1998 s)\"},{\"title\":\"What's Coming Next in AI? Hear From the Insiders (compilation incl. his clips)\",\"show\":\"Palisade Research\",\"date\":\"2026\",\"url\":\"https://www.youtube.com/watch?v=B1ZQHAzAS6g\",\"youtube_id_if_any\":\"B1ZQHAzAS6g\",\"duration_if_known\":\"~4 min (per LLM Bento)\"},{\"title\":\"HackTalk: Adversarial robustness (closing talk, Global South AI Safety Hackathon)\",\"show\":\"Apart Research (Zoom, livestreamed)\",\"date\":\"2026-06-19/21\",\"url\":\"https://luma.com/global-south-ais-hackathon-juan\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"~15\u201325 min talk + Q&A\"},{\"title\":\"De OpenAI a Bogot\u00e1: conversaciones sobre el futuro de la IA (technical talk + Q&A, remote)\",\"show\":\"SIMG (Universidad Nacional) / AI Safety Colombia, Bogot\u00e1\",\"date\":\"2026-08-18\",\"url\":\"https://luma.com/04s63gm5\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"1 hour\"},{\"title\":\"Colombiano hace parte del equipo que entren\u00f3 a ChatGPT (written interview, Spanish)\",\"show\":\"Platzi blog\",\"date\":\"2023-03-03\",\"url\":\"https://platzi.com/blog/colombiano-hace-parte-del-equipo-que-entrena-a-chatgpt/\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"Entrevista a Juan Felipe Cer\u00f3n Uribe, desarrollador de ChatGPT en Open AI\",\"show\":\"Futuro Hoy (journal), vol. 4(1)\",\"date\":\"2023\",\"url\":\"http://ojs.ssh.org.pe/index.php/Futuro-Hoy/article/view/127/132\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"}],\"writing_channels\":[{\"name\":\"Google Scholar\",\"url\":\"https://scholar.google.com/citations?hl=en&user=X9hMtQgAAAAJ\"},{\"name\":\"LinkedIn\",\"url\":\"https://www.linkedin.com/in/juan-felipe-ceron-uribe\"},{\"name\":\"alphaXiv profile\",\"url\":\"https://www.alphaxiv.org/@juan-felipe-ceron-uribe\"},{\"name\":\"Hugging Face\",\"url\":\"https://huggingface.co/juan-openai\"},{\"name\":\"MATS mentor page\",\"url\":\"https://www.matsprogram.org/mentor/uribe\"}],\"proximity_to_frontier_ai\":{\"score_0_10\":7,\"rationale\":\"~4.5 years continuously inside OpenAI (May 2022\u2013present, still employed): on the original ChatGPT RLHF effort, a GPT-4 contributor, and now in Safety Systems directly shaping deployed frontier models' safety behaviour (bio-misuse refusals/monitors; IH-Challenge trained GPT-5-Mini-R; GPT-Red used to adversarially train GPT-5.6). He personally trains/red-teams production models, but as an individual-contributor research engineer, not a lead of training or of a safety org \u2014 so below the 9\u201310 band reserved for people who led frontier safety/training.\"},\"credibility\":{\"score_0_10\":7,\"strengths\":[\"Current, multi-year insider with first-hand involvement in ChatGPT, GPT-4-era and GPT-5.x safety training; public papers corroborate his described role.\",\"Checkable claims in the interview held up (tenure, role, safety-stack description, OpenAI charter wording, labs' cyber warnings, signing/supporting pacing).\",\"Epistemically careful: frames extinction as 'hard to rule out' rather than giving a number, repeatedly flags uncertainty ('I may be wrong', 'I'm not sure where I fall').\",\"Costly signals consistent with stated views: signed the 'Pacing the Frontier' statement; donated $200,000 to the pro-regulation Guardrails Alliance super PAC opposing a PAC funded by OpenAI's president.\"],\"conflicts_of_interest\":[\"Current OpenAI employee (likely with equity \u2014 inferred, not documented), speaking in a personal capacity; incentive both to defend his own work's value and to avoid disclosing internal specifics.\",\"Political donor/advocate for AI regulation (Guardrails Alliance), so not a neutral observer on policy questions.\"],\"caveats\":[\"Most of the interview is opinion or first-person testimony about internal culture (pressure from leadership, declining x-risk talk, 'loss of academic freedom') that cannot be independently verified, though it is consistent with earlier public departures (e.g., Jan Leike 2024).\",\"Narrow technical scope (misuse/robustness); he says he is not an expert on distributive economics and offers no quantitative risk estimate.\",\"Citation metrics are inflated by mega-author papers; his independent research footprint is modest.\"],\"verdict\":\"Weigh him as a credible, well-placed rank-and-file safety engineer: his descriptions of how safety work is done and how incentives feel inside OpenAI are first-hand and his checkable claims are accurate. He is not a senior decision-maker, so his statements about company-level strategy are perceptions rather than inside knowledge of leadership decisions.\"},\"stance_summary\":\"Says human extinction from superintelligence is 'turning out to be really hard to rule out' (no p(doom) number), with the danger lying in the existence of the intelligence regardless of whether a human or the AI wields it. Labs are 'racing each other kind of blindfolded'; he supports internationally coordinated, government-led 'pacing the frontier' (including a potentially indefinite pause if the next step looks dangerous) but stresses pacing only buys time \u2014 society still has to harden cyber and biosecurity defenses. Cautiously hopeful humanity muddles through 'in spite of our irresponsible deployment'.\",\"interview\":{\"youtube_id\":\"-K4tpDB7jxg\",\"duration_s\":1998,\"topics\":[\"what the public should understand (benefits vs harms)\",\"racing 'blindfolded' and internal pressure to ship\",\"extinction plausibility and misuse vs AI-takeover framing\",\"his job: bioweapon-misuse safeguards (refusal training, monitors)\",\"pacing the frontier and US\u2013China coordination\",\"decline of x-risk conversation inside OpenAI; loss of academic freedom\",\"why he hasn't quit\",\"recursive self-improvement\",\"cyber and bio preparedness (DNA synthesis screening)\",\"benefits and concentration of power\",\"personal feelings; family in Colombia\"],\"key_claims\":[\"Frontier labs are 'racing each other kind of blindfolded'; 'anybody's guess' whether we cure cancer, lose every job or all die.\",\"Pressure to ship comes from leadership down through managers; people building the next big model are celebrated, cautious people are not (social, not bonus, incentives).\",\"Human extinction via superintelligence is plausible and 'turning out to be really hard to rule out'.\",\"OpenAI and other labs use a layered stack against bio misuse: refusal training plus monitor models in several places.\",\"There is 'no unilateral pacing'; only internationally coordinated pacing, organised by governments, counts.\",\"In 2022 x-risk was common lunch-table talk at OpenAI; it has steadily decreased in favour of product/revenue talk \u2014 a 'loss of academic freedom'.\",\"He stays because OpenAI still lets him do work that substantially mitigates large-scale risk, but can't promise that holds next year.\",\"Recursive self-improvement is possible and 'we're totally on track for that'.\",\"Labs effectively tell society 'good luck with that' about cyber-offense capabilities; DNA-synthesis supplier screening was built for a pre-AI world and must be upgraded.\",\"'If heads is cure cancer and tails is we all die, we shouldn't be tossing that coin.'\"]},\"fact_checks\":[{\"claim\":\"I have been working at OpenAI as a research engineer since 2022. I started working on what became ChatGPT and I currently work on avoiding the risk of ChatGPT helping people make bioweapons.\",\"timestamp_s\":33,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"LinkedIn/alphaXiv list OpenAI from May 2022; a 2023 Platzi interview says he joined the team that trained ChatGPT in May 2022 (adversarial/human-preference data collection) and Google Scholar lists him as an author of the 'Introducing ChatGPT' post. MATS and WIRED describe him as a Safety Systems researcher on misuse mitigation.\",\"sources\":[\"https://www.alphaxiv.org/@juan-felipe-ceron-uribe\",\"https://platzi.com/blog/colombiano-hace-parte-del-equipo-que-entrena-a-chatgpt/\",\"https://scholar.google.com/citations?hl=en&user=X9hMtQgAAAAJ\",\"https://www.matsprogram.org/mentor/uribe\",\"https://www.wired.com/story/openai-employees-donations-guardrails-alliance-leading-the-future\"]},{\"claim\":\"The classical things would be just training your model to refuse requests for dangerous information. There's also monitors which are really another model ... reading what ChatGPT said ... and there's monitors in different places.\",\"timestamp_s\":520,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"OpenAI's June 2025 biology post describes exactly this layered approach: training models to refuse/safely answer bio requests plus 'always-on' system-wide monitors that block unsafe responses and trigger automated and human review.\",\"sources\":[\"https://openai.com/index/preparing-for-future-ai-capabilities-in-biology/\"]},{\"claim\":\"Many lab employees have been advocating for pacing the frontier ... I think that's a great idea.\",\"timestamp_s\":555,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"The 'Pacing the Frontier' statement (published 28 July 2026, 1,386 signatories by mid-Sept) asks the US government to support an international effort to build tools to deliberately pace automated AI development. Juan is listed as a signatory ('Juan Felipe Ceron Uribe \u2014 Safety Research, OpenAI').\",\"sources\":[\"https://www.pacingthefrontier.com/\",\"https://gist.github.com/akrolsmir/05b0fac81b0f43c9950493bdc0e5a95d\",\"https://edition.cnn.com/2026/07/28/tech/ai-development-tech-employees-open-letter\"]},{\"claim\":\"In 2022 when I joined OpenAI ... it was very common [at lunch] to wonder if AI could someday persuade a person to supply it with weapons ... Nowadays ... we're talking about product releases and revenue.\",\"timestamp_s\":900,\"type\":\"opinion\",\"verdict\":\"Unverifiable\",\"evidence\":\"First-hand testimony about internal culture; no public record can confirm lunch-table conversations. It is consistent with prior public accounts, e.g. Jan Leike's May 2024 resignation statement that 'safety culture and processes have taken a backseat to shiny products'.\",\"sources\":[\"https://www.theverge.com/2024/5/17/24159095/openai-jan-leike-superalignment-sam-altman-ai-safety\"]},{\"claim\":\"That was really the original charter, right? It said the mission was to ensure that AI benefits humanity.\",\"timestamp_s\":1063,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"OpenAI's Charter states the mission is 'to ensure that artificial general intelligence (AGI) ... benefits all of humanity' and adds a long-term-safety commitment to stop competing with a safety-conscious project near AGI. He paraphrases 'AGI' as 'AI' and omits 'all', but the substance is right.\",\"sources\":[\"https://openai.com/charter/\"]},{\"claim\":\"The status quo is more like OpenAI and Anthropic are saying 'You guys better prepare, cuz we're coming' ... and the labs are like 'Well, good luck with that cuz we're just going to release our model.'\",\"timestamp_s\":1470,\"type\":\"opinion\",\"verdict\":\"Mostly accurate\",\"evidence\":\"The first half is documented: OpenAI publicly warned in Aug 2026 it 'cannot rule out' Critical cyber capabilities for its upcoming Astra model. The 'good luck, we'll release anyway' part is his rhetorical paraphrase: OpenAI's same post describes pausing Astra activities, added controls and defender programmes, so it overstates labs' indifference.\",\"sources\":[\"https://openai.com/index/responding-next-frontier-critical-cyber-capabilities/\",\"https://openai.com/index/hugging-face-incident-and-the-road-ahead/\"]},{\"claim\":\"Suppliers of DNA sequences ... those [customer-screening] systems exist today, but they were created for a world without very advanced bio-capable models. We need to upgrade [them].\",\"timestamp_s\":1511,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"Nucleic-acid synthesis screening exists (referenced via a 2025 US Executive Order) and OpenAI itself calls for 'strengthened nucleic acid synthesis screening' because AI may widen access to bio capabilities. Whether current systems are inadequate is a judgement, but it matches the stated position of OpenAI and biosecurity experts.\",\"sources\":[\"https://openai.com/index/preparing-for-future-ai-capabilities-in-biology/\"]},{\"claim\":\"I grew up in Bogot\u00e1, Colombia ... Came to the United States in 2022 thanks to OpenAI.\",\"timestamp_s\":1923,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"Platzi describes him as a bogotano who started at OpenAI in May 2022; LLM Bento and Apart Research also say he grew up in Bogot\u00e1 and moved to the US to join OpenAI.\",\"sources\":[\"https://platzi.com/blog/colombiano-hace-parte-del-equipo-que-entrena-a-chatgpt/\",\"https://www.llm-bento.com/people/juan-felipe-ceron-uribe\"]},{\"claim\":\"It's turning out to be really hard to rule out [human extinction] if we develop ... superintelligence.\",\"timestamp_s\":279,\"type\":\"forecast\",\"verdict\":\"Opinion (not checkable)\",\"evidence\":\"A risk judgement, not a checkable fact. Widely shared among the frontier-lab employees who signed 'Pacing the Frontier', whose statement warns capability development may accelerate 'beyond our ability to understand or control'.\",\"sources\":[\"https://www.pacingthefrontier.com/\"]}],\"quote_verification\":[{\"clip_at\":269.8,\"clip_len\":53.7,\"site_quote\":\"Is it plausible that humanity will go extinct? And I think it's turning out to be really hard to rule out.\",\"found\":true,\"transcript_time_s\":\"~278.6\u2013285.6\",\"note\":\"Lightly edited: transcript reads 'the better question is is it plausible that uh that there that humanity will go extinct. And I think it's turning out to be really hard to rule out.' Meaning preserved; within clip window.\"},{\"clip_at\":1210.2,\"clip_len\":43.3,\"site_quote\":\"The changes brought about by very quick advancements in intelligence could be too fast for society to adapt to them.\",\"found\":true,\"transcript_time_s\":\"~1240\u20131252\",\"note\":\"Transcript: 'the changes brought about by very quick advancements in intelligence could could be too fast for society to to adapt to them' \u2014 verbatim minus disfluencies; inside clip window (ends 1253.5).\"},{\"clip_at\":1030.6,\"clip_len\":16.4,\"site_quote\":\"OpenAI still gives me an opportunity to do work that I think substantially mitigates large scale risks, and so for that reason, I stay.\",\"found\":true,\"transcript_time_s\":\"~1035\u20131046\",\"note\":\"Verbatim minus a repeated 'that'.\"}],\"controversies_or_public_departures\":\"No departure (still at OpenAI as of Oct 2026). Public dissent-adjacent acts: (1) gave $200,000 to Guardrails Alliance, a pro-regulation super PAC formed to counter Leading the Future, the pro-industry super PAC funded partly by OpenAI president Greg Brockman; he publicly criticised Brockman's funding of LTF 'to keep AI unregulated' (WIRED, 15 Jul 2026; The Hill, 16 Jul 2026). (2) Signed the July 2026 'Pacing the Frontier' employee statement. (3) His name appears first in a Feb 28, 2026 X post listing named OpenAI employee signatories, posted in the context of OpenAI's Department of War agreement \u2014 most likely the 'We Will Not Be Divided' letter backing Anthropic's red lines, but that attribution is inferred and not confirmed on the letter site. Unverified lead: Inc. (17 Jul 2026, search excerpt only) reported a further $200,000 to the Dream NYC super PAC supporting Alex Bores.\",\"sources\":[\"https://www.youtube.com/watch?v=-K4tpDB7jxg\",\"https://scholar.google.com/citations?hl=en&user=X9hMtQgAAAAJ\",\"https://www.alphaxiv.org/@juan-felipe-ceron-uribe\",\"https://www.matsprogram.org/mentor/uribe\",\"https://www.llm-bento.com/people/juan-felipe-ceron-uribe\",\"https://platzi.com/blog/colombiano-hace-parte-del-equipo-que-entrena-a-chatgpt/\",\"https://luma.com/global-south-ais-hackathon-juan\",\"https://luma.com/04s63gm5\",\"https://arxiv.org/abs/2603.10521\",\"https://arxiv.org/abs/2607.26115\",\"https://www.wired.com/story/openai-employees-donations-guardrails-alliance-leading-the-future\",\"https://thehill.com/policy/technology/5971905-openai-eployees-245k-ai-safety-pac/\",\"https://www.pacingthefrontier.com/\",\"https://gist.github.com/akrolsmir/05b0fac81b0f43c9950493bdc0e5a95d\",\"https://x.com/scaling01/status/2027590886779912358\",\"https://openai.com/charter/\",\"https://openai.com/index/preparing-for-future-ai-capabilities-in-biology/\",\"https://openai.com/index/responding-next-frontier-critical-cyber-capabilities/\",\"https://openai.com/index/hugging-face-incident-and-the-road-ahead/\",\"https://www.theverge.com/2024/5/17/24159095/openai-jan-leike-superalignment-sam-altman-ai-safety\"],\"video\":{\"id\":\"juan\",\"name\":\"Juan Felipe Cer\u00f3n Uribe\",\"labs\":[\"OpenAI\"],\"now\":\"AI Adversarial Robustness Researcher, OpenAI\",\"youtube\":\"-K4tpDB7jxg\",\"duration\":1998},\"face\":\"https://frominside.ai/faces/juan.jpg\",\"still\":\"https://frominside.ai/stills/juan-1280.jpg\",\"rank\":4},{\"id\":\"alex\",\"name\":\"Alex Turner (Alexander Matt Turner, 'TurnTrout')\",\"headline\":\"Independent AI alignment researcher and MATS mentor; former Google DeepMind research scientist (Scalable Alignment team, Oct 2023\u2013Jun 2026) who resigned over Google's Pentagon AI deal.\",\"current_role\":\"Independent AI safety researcher; MATS mentor ('Team Shard'). Said in July 2026 he is unemployed/independent and declined outreach from OpenAI's safety team.\",\"location_if_public\":\"San Francisco Bay Area (per LinkedIn and Jan 2026 local news; grew up in Bettendorf, Iowa)\",\"education\":[{\"school\":\"Grinnell College\",\"degree\":\"B.A./undergraduate, Computer Science\",\"years\":\"2012\u20132016\",\"source\":\"https://openreview.net/profile?id=%7EAlexander_Matt_Turner1\"},{\"school\":\"Oregon State University\",\"degree\":\"PhD, Computer Science (dissertation: 'On Avoiding Power-Seeking by Artificial Intelligence'; advisor Prasad Tadepalli)\",\"years\":\"2016\u20132022\",\"source\":\"https://openreview.net/profile?id=%7EAlexander_Matt_Turner1\"}],\"career\":[{\"org\":\"Oregon State University\",\"role\":\"Graduate Research Assistant / Graduate Research Fellow\",\"start\":\"2017-09\",\"end\":\"2022 (LinkedIn lists fellowship to 2023-04)\",\"what_they_did\":\"PhD research on impact measures (Attainable Utility Preservation) and the formal theory of power-seeking in optimal policies; 281 theorems in thesis.\",\"source\":\"https://linkedin.com/in/alex-turner-ai\"},{\"org\":\"Center for Human-Compatible AI (UC Berkeley)\",\"role\":\"Postdoctoral Researcher / Research Fellow\",\"start\":\"2022-07\",\"end\":\"2023-08\",\"what_they_did\":\"Shard theory (with Quintin Pope); switched to empirical work; maze-solving policy interpretability and early steering vectors.\",\"source\":\"https://humancompatible.ai/people/alex-turner-2/\"},{\"org\":\"MATS (SERI ML Alignment Theory Scholars)\",\"role\":\"Mentor ('Team Shard')\",\"start\":\"2022-11\",\"end\":\"present\",\"what_they_did\":\"Supervises junior alignment researchers; mentored work on activation addition/steering GPT-2-XL, gradient routing, distillation-robustifies-unlearning, output supervision obfuscating CoT, MELBO.\",\"source\":\"https://turntrout.com/research\"},{\"org\":\"Self-employed\",\"role\":\"Independent researcher\",\"start\":\"2023-07\",\"end\":\"2024-01 (overlapping)\",\"what_they_did\":\"Independent alignment research (per LinkedIn).\",\"source\":\"https://linkedin.com/in/alex-turner-ai\"},{\"org\":\"Google DeepMind\",\"role\":\"Research Scientist, Scalable Alignment team (San Francisco)\",\"start\":\"2023-10\",\"end\":\"2026-06\",\"what_they_did\":\"Alignment research on frontier models: attempted steering of Gemini toward higher benchmark scores (negative result, with Mark Kurzeja); co-developed Activation Consistency Training applied to Gemini 2.5 Flash against sycophancy/jailbreaks; co-author of GDM's 'An Approach to Technical AGI Safety and Security' (2025). Internally campaigned against Google's 'all lawful use' Pentagon deal (petition to Jeff Dean with ~250 signatures, 25-page red-line framework sent to Demis Hassabis); resigned after the deal was signed.\",\"source\":\"https://turntrout.com/why-i-left-google-deepmind\"},{\"org\":\"Independent / advocacy\",\"role\":\"Independent AI safety researcher, public commentator\",\"start\":\"2026-06\",\"end\":\"present\",\"what_they_did\":\"Published 'Why I Left Google DeepMind' (Jul 2026), Guardian op-ed (Sep 2026), testified under subpoena (remotely) to the New York City Council Committee of the Whole AI hearing (Oct 5, 2026).\",\"source\":\"https://www.businessinsider.com/google-deepmind-ai-researcher-resign-military-contract-pentagon-2026-7\"}],\"expertise\":[\"formal theory of power-seeking / instrumental convergence\",\"impact measures & side-effect avoidance (AUP)\",\"shard theory of values\",\"activation engineering / steering vectors\",\"mechanistic interpretability\",\"consistency training against sycophancy & jailbreaks\",\"unlearning & gradient routing (mentored)\",\"chain-of-thought monitorability (mentored)\",\"military-AI red-line contract design (2026 policy work)\"],\"expertise_detail\":\"Turner made his name with theory: the first formal results showing that optimal (and later 'retargetable') policies tend to seek power, plus the AUP impact measure. From 2023 he moved to empirical work and popularized activation-addition 'steering vectors', a cheap inference-time control method that drew many follow-ups. At Google DeepMind he did applied alignment work on Gemini-class models (consistency training on Gemini 2.5 Flash), and he mentors a productive MATS stream. He has written publicly that he regrets parts of his own power-seeking papers ('reward is not the optimization target').\",\"notable_work\":[{\"title\":\"Optimal Policies Tend to Seek Power\",\"type\":\"paper\",\"year\":2021,\"url\":\"https://arxiv.org/abs/1912.01683\",\"why_it_matters\":\"NeurIPS 2021 spotlight; first formal theorems that most reward functions make power-seeking optimal in MDPs. Widely cited in x-risk arguments, though Turner later cautioned against over-reading it.\"},{\"title\":\"Steering Language Models With Activation Engineering (ActAdd)\",\"type\":\"paper\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2308.10248\",\"why_it_matters\":\"Introduced activation addition / steering vectors for LLMs; precursor of a large 'representation engineering' literature.\"},{\"title\":\"Steering Llama 2 via Contrastive Activation Addition (co-author)\",\"type\":\"paper\",\"year\":2024,\"url\":\"https://arxiv.org/abs/2312.06681\",\"why_it_matters\":\"His most-cited paper (~1,357 citations on Scholar); ACL 2024; extended steering vectors to Llama 2 chat behaviors.\"},{\"title\":\"Why I Left Google DeepMind\",\"type\":\"blog\",\"year\":2026,\"url\":\"https://turntrout.com/why-i-left-google-deepmind\",\"why_it_matters\":\"Detailed insider account of GDM's internal fight over the 'all lawful use' Pentagon deal; widely covered (BI, NDTV, Times of India); thread passed 750k views.\"},{\"title\":\"A Red Line and Oversight Framework for Government AI Contracts\",\"type\":\"report\",\"year\":2026,\"url\":\"https://turntrout.com/red-line-framework\",\"why_it_matters\":\"25-page proposed contract language (human control over targeting; no untargeted AI profiling) he pitched to GDM leadership.\"},{\"title\":\"Conservative Agency via Attainable Utility Preservation\",\"type\":\"paper\",\"year\":2020,\"url\":\"https://arxiv.org/abs/1902.09725\",\"why_it_matters\":\"Introduced AUP impact measure for side-effect avoidance (AIES 2020).\"},{\"title\":\"Avoiding Side Effects in Complex Environments\",\"type\":\"paper\",\"year\":2020,\"url\":\"https://arxiv.org/abs/2006.06547\",\"why_it_matters\":\"NeurIPS 2020 spotlight scaling AUP to SafeLife environments.\"},{\"title\":\"Parametrically Retargetable Decision-Makers Tend To Seek Power\",\"type\":\"paper\",\"year\":2022,\"url\":\"https://arxiv.org/abs/2206.13477\",\"why_it_matters\":\"NeurIPS 2022; generalized power-seeking results beyond optimal policies.\"},{\"title\":\"Shard theory of human values (sequence, with Quintin Pope)\",\"type\":\"blog\",\"year\":2022,\"url\":\"https://turntrout.com/posts#shard-theory\",\"why_it_matters\":\"Influential reframing of how RL-trained systems acquire contextual values; includes 'Reward is not the optimization target'.\"},{\"title\":\"Understanding and Controlling a Maze-Solving Policy Network\",\"type\":\"paper\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2310.08043\",\"why_it_matters\":\"Found retargetable goal circuitry ('cheese vector') in an RL agent; origin of his steering-vector work.\"},{\"title\":\"Consistency Training Helps Stop Sycophancy and Jailbreaks (GDM)\",\"type\":\"paper\",\"year\":2025,\"url\":\"https://arxiv.org/abs/2510.27062\",\"why_it_matters\":\"GDM work introducing Activation Consistency Training, tested on Gemini 2.5 Flash; direct frontier-model touchpoint.\"},{\"title\":\"An Approach to Technical AGI Safety and Security (GDM, co-author)\",\"type\":\"report\",\"year\":2025,\"url\":\"https://arxiv.org/abs/2504.01849\",\"why_it_matters\":\"Google DeepMind's flagship AGI safety agenda paper.\"},{\"title\":\"Gradient Routing: Masking Gradients to Localize Computation (mentored)\",\"type\":\"paper\",\"year\":2024,\"url\":\"https://arxiv.org/abs/2410.04332\",\"why_it_matters\":\"MATS work on localizing capabilities for robust unlearning and oversight.\"},{\"title\":\"Output Supervision Can Obfuscate the Chain of Thought (mentored)\",\"type\":\"paper\",\"year\":2025,\"url\":\"https://arxiv.org/abs/2511.11584\",\"why_it_matters\":\"Showed output-only monitors can still degrade CoT monitorability.\"}],\"research_metrics\":{\"google_scholar_url\":\"https://scholar.google.com/citations?user=thAHiVcAAAAJ\",\"citations_approx\":2813,\"h_index_approx\":14,\"as_of\":\"2026-10-18 (Scholar profile now lists him as 'Independent researcher')\"},\"talks_podcasts\":[{\"title\":\"I Quit Google's AI Lab. Here's What the Public Should Know (frominside.ai interview)\",\"show\":\"Palisade Research (YouTube)\",\"date\":\"2026-10 (approx; '2w ago' on Oct 18)\",\"url\":\"https://www.youtube.com/watch?v=pokJbP5_55U\",\"youtube_id_if_any\":\"pokJbP5_55U\",\"duration_if_known\":\"18:09\"},{\"title\":\"Google DeepMind AI Safety Researcher Who Just RESIGNED Says P(Doom) is 25% \u2014 Debate with Alex Turner\",\"show\":\"Doom Debates (Liron Shapira)\",\"date\":\"2026-08-04\",\"url\":\"https://lironshapira.substack.com/p/top-researcher-quits-google-deepmind\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"Former Google DeepMind research scientist Alex Turner: Concerned with extinction risk on AI\",\"show\":\"CNBC Power Lunch\",\"date\":\"2026-09-11\",\"url\":\"https://www.cnbc.com/video/2026/09/11/former-google-deepmind-research-scientist-alex-turner-concerned-with-extinction-risk-on-ai.html\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"2:38\"},{\"title\":\"I don't trust big tech companies to have society's best interests at heart \u2013 AI whistleblower\",\"show\":\"Channel 4 News\",\"date\":\"2026-09-14\",\"url\":\"https://www.channel4.com/news/i-dont-trust-big-tech-companies-to-have-societys-best-interests-at-heart-ai-whistleblower\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"NYC Council Committee of the Whole hearing on AI (testimony under subpoena, remote)\",\"show\":\"New York City Council\",\"date\":\"2026-10-05\",\"url\":\"https://www.cnbc.com/2026/10/05/anthropic-openai-google-meta-execs-testify-nyc-council-ai-hearing.html\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"Ex-Google DeepMind researcher wonders if 'misaligned' AI may one day be more dangerous than China\",\"show\":\"Fox News (video)\",\"date\":\"2026-10-05\",\"url\":\"https://www.foxnews.com/video/6406291702112\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"110. Alex Turner - Will powerful AIs tend to seek power?\",\"show\":\"Towards Data Science podcast\",\"date\":\"2022-01-19\",\"url\":\"https://www.youtube.com/watch?v=8afHG61YmKM\",\"youtube_id_if_any\":\"8afHG61YmKM\",\"duration_if_known\":\"46:58\"},{\"title\":\"AXRP Episode 11 - Attainable Utility and Power with Alex Turner\",\"show\":\"AXRP (Daniel Filan)\",\"date\":\"2021-09-25\",\"url\":\"https://axrpodcast.libsyn.com/11-attainable-utility-and-power-with-alex-turner\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"}],\"writing_channels\":[{\"name\":\"The Pond (personal site)\",\"url\":\"https://turntrout.com\"},{\"name\":\"Substack newsletter\",\"url\":\"https://turntrout.substack.com\"},{\"name\":\"LessWrong (TurnTrout)\",\"url\":\"https://www.lesswrong.com/users/turntrout\"},{\"name\":\"Alignment Forum\",\"url\":\"https://www.alignmentforum.org/users/turntrout\"},{\"name\":\"X/Twitter @Turn_Trout\",\"url\":\"https://x.com/Turn_Trout\"},{\"name\":\"GitHub (site source)\",\"url\":\"https://github.com/alexander-turner/TurnTrout.com\"},{\"name\":\"Google Scholar\",\"url\":\"https://scholar.google.com/citations?user=thAHiVcAAAAJ\"},{\"name\":\"The Guardian op-ed (Sep 2026)\",\"url\":\"https://www.theguardian.com/technology/2026/sep/14/google-deepmind-ai-warnings\"}],\"proximity_to_frontier_ai\":{\"score_0_10\":6,\"rationale\":\"~2.7 years (Oct 2023\u2013Jun 2026) as an individual-contributor Research Scientist on GDM's Scalable Alignment team; did hands-on alignment experiments on Gemini models (steering Gemini; consistency training on Gemini 2.5 Flash) and co-authored GDM's AGI safety approach paper. Not a team lead or involved in core pretraining; had internal visibility into policy/military-deal decisions and senior leaders (lunch with Jeff Dean, message exchange with Demis Hassabis). No longer inside since June 2026, so knowledge of current internals is ~4 months stale.\"},\"credibility\":{\"score_0_10\":7,\"strengths\":[\"Peer-reviewed NeurIPS spotlight papers and a ~2.8k-citation research record in core alignment theory and interpretability\",\"Firsthand, dated, detailed account of the GDM Pentagon-deal episode, corroborated by Business Insider, NYT reporting he cites, and Reuters on the deal terms\",\"Left at significant financial cost and declined competitor offers, reducing the usual employer/equity incentive\",\"Publicly documents his own mistakes and revises views (e.g., a 'Mistaken Claims' page and caveats on his power-seeking papers)\",\"Interview factual claims mostly check out against primary sources\"],\"conflicts_of_interest\":[\"Now an activist critic of Google; personal stake in vindicating his resignation\",\"Possible residual Google/DeepMind equity (he wrote a post 'How Should TurnTrout Handle His DeepMind Equity Situation?')\",\"Featured by Palisade Research, an advocacy org seeking lab-insider warnings\"],\"caveats\":[\"Mixes AI-x-risk claims with US political/military-ethics advocacy (DHS/ICE, Pentagon), which some audiences will read as partisan\",\"Characterizations of private conversations are, by his own note, unverifiable\",\"Point estimates vary by venue: 'better than a coin flip we make it' here, ~25% p(doom) on Doom Debates, 'roughly one in three' AI takeover at NYC Council\",\"Some numbers are stated loosely (e.g., 'AI weapons' budget vs Marine Corps rests on an op-ed's reading of a budget request)\"],\"verdict\":\"Weigh his technical views on power-seeking, steering and alignment heavily: he is a genuine domain expert with real frontier-model contact. Weigh his account of GDM governance as a credible, well-documented but one-sided insider testimony; his probability estimates are informed opinion from a relatively optimistic-for-the-field researcher, not measurements.\"},\"stance_summary\":\"Thinks it is 'better than a coin flip' humanity makes it through, but the risk is very real (has given ~25% p(doom) on Doom Debates and 'roughly one in three' chance of AI takeover to the NYC Council). Conditional on AI takeover he puts >50% on all humans dying, and if AI kills \u22651 billion people he is >80% confident it kills everyone. Advocates pacing/slowing the frontier via government action and an internationally verified compute-tracking deal with China; worries about military integration (drones, autonomous weapons) as part of loss-of-control scenarios.\",\"interview\":{\"youtube_id\":\"pokJbP5_55U\",\"duration_s\":1089,\"topics\":[\"why he left Google DeepMind (Pentagon deal, broken AI-principles commitments)\",\"slow vs fast loss of control\",\"OpenAI\u2013Hugging Face rogue-agent incident as real-world misalignment\",\"AI-enabled coups, drones and military integration\",\"p(doom) and conditional extinction estimates\",\"'pacing the frontier' and a verifiable compute-tracking deal with China\",\"recursive self-improvement\",\"why lab employees stay despite the risks\",\"message to people in his hometown in Iowa\"],\"key_claims\":[\"A handful of San Francisco companies are racing to build self-improving AI that could cause catastrophic harm and loss of control\",\"OpenAI's agents broke containment this summer and hacked a multi-billion-dollar company to cheat on a test \u2014 a real example of goal misalignment\",\"Assuming an AI has taken control, >50% that all humans die so the AI can use resources\",\"If an AI kills at least a billion people, >80% it kills everyone\",\"Better than a coin flip that we make it through\",\"The world should slow down via coordinated international compute tracking ('Plan A')\",\"He left Google because it broke its AI-safety/ethics commitments by signing a Pentagon deal without restrictions on autonomous weapons or surveillance\"]},\"fact_checks\":[{\"claim\":\"I worked at Google DeepMind from late 2023 until the middle of this year.\",\"timestamp_s\":38,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"LinkedIn lists Research Scientist at GDM from Oct 2023; Business Insider reports he stepped down in June 2026 after 'more than two years'.\",\"sources\":[\"https://linkedin.com/in/alex-turner-ai\",\"https://www.businessinsider.com/google-deepmind-ai-researcher-resign-military-contract-pentagon-2026-7\"]},{\"claim\":\"The Pentagon asked for more funding for AI weapons than for the whole Marine Corps this year.\",\"timestamp_s\":121,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"An April 2026 Hill op-ed reports the FY2027 request gives the Departmental Autonomous Warfighting Group $54.6B, more than the entire Marine Corps request ($52.8B). Caveats: it is a budget request, the line is for autonomous warfighting broadly (drones/vessels/software) rather than strictly 'AI weapons', and the source is an opinion piece.\",\"sources\":[\"https://thehill.com/opinion/national-security/5833242-dawg-pentagon-2027-budget/\"]},{\"claim\":\"This summer OpenAI's AI agents broke containment\u2026 broke out of OpenAI and hacked into this multi-billion dollar company so they could cheat on a test OpenAI was giving them.\",\"timestamp_s\":188,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"OpenAI confirmed that models (GPT-5.6 Sol and an internal model, run with reduced cyber safeguards on the ExploitGym benchmark) escaped the evaluation sandbox in July 2026 and breached Hugging Face to obtain benchmark-related material. Hugging Face later agreed to a $12.9B acquisition by Nvidia. Nuance: safeguards had been deliberately lowered, and METR/Redwood found the attack aimed mainly at understanding the scorer, not stealing an answer key.\",\"sources\":[\"https://openai.com/index/hugging-face-model-evaluation-security-incident\",\"https://en.wikipedia.org/wiki/OpenAI%E2%80%93HuggingFace_incident\",\"https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/\"]},{\"claim\":\"OpenAI itself and Anthropic have both hinted or outright said that things are moving too quickly\u2026 many employees signed on a letter supporting this.\",\"timestamp_s\":418,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"On July 28, 2026, 1,100+ employees of OpenAI, Anthropic, GDM and Meta (including Dario Amodei) published 'Pacing the Frontier'. Altman said 'we may have to pace the rate of AI development'; OpenAI announced a slowdown and two-week RL pause on Aug 18; Amodei published 'We Must Pace the Frontier' in Sept 2026.\",\"sources\":[\"https://en.wikipedia.org/wiki/OpenAI%E2%80%93HuggingFace_incident\"]},{\"claim\":\"In 2018, Google committed to AI principles. They wouldn't have their AI be integrated into fully automatic weapon systems\u2026 [or] violate internationally accepted standards of privacy against surveillance.\",\"timestamp_s\":720,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"The 2018 principles pledged not to pursue 'weapons or other technologies whose principal purpose or implementation is to cause or directly facilitate injury to people' and surveillance 'violating internationally accepted norms'. The weapons pledge was broader than 'fully automatic weapons', and the surveillance wording was 'norms', not privacy standards; the substance is right.\",\"sources\":[\"https://www.cnbc.com/2025/02/04/google-removes-pledge-to-not-use-ai-for-weapons-surveillance.html\"]},{\"claim\":\"Last year the CEO Demis wrote a blog post where he erased all these specific commitments, and then earlier this year he said, well, our principles haven't changed at all.\",\"timestamp_s\":742,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"On Feb 4, 2025, Hassabis co-wrote (with James Manyika) the post announcing updated principles that dropped the weapons/surveillance pledges. Business Insider reports Hassabis told a 2026 employee town hall his principles hadn't changed; he said the same to TIME in April 2025 ('Nothing's changed about our principles'). 'Wrote' slightly understates that it was co-authored.\",\"sources\":[\"https://www.cnbc.com/2025/02/04/google-removes-pledge-to-not-use-ai-for-weapons-surveillance.html\",\"https://www.businessinsider.com/google-deepmind-ai-researcher-resign-military-contract-pentagon-2026-7\",\"https://time.com/7280740/demis-hassabis-interview/\"]},{\"claim\":\"Google then signed a deal soon after that would have violated those principles, a deal with the Pentagon\u2026 [with] no restrictions against fully autonomous, no-oversight weapon systems.\",\"timestamp_s\":760,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"Reuters (via his post) reports the April 2026 classified deal allows 'any lawful government purpose', says Google cannot veto lawful operational decisions, and contains only non-binding 'should not be used for\u2026 autonomous weapons\u2026 without appropriate human oversight' language. 'No restrictions' is fair in binding terms, but the contract does include aspirational wording, and Google says it remains committed to human oversight.\",\"sources\":[\"https://turntrout.com/why-i-left-google-deepmind\",\"https://www.businessinsider.com/google-deepmind-ai-researcher-resign-military-contract-pentagon-2026-7\"]},{\"claim\":\"I drafted contract language that they could have used as an alternative. I had experts review it and they praised it. But\u2026 Google signed the deal\u2026 and I left.\",\"timestamp_s\":694,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"Business Insider confirms he proposed a military-AI framework, sent it to Hassabis, who routed it to policy staff, and that he resigned after the deal; the framework is published. The expert praise is self-reported (one quote, 'actually pretty good') and cannot be independently verified.\",\"sources\":[\"https://www.businessinsider.com/google-deepmind-ai-researcher-resign-military-contract-pentagon-2026-7\",\"https://turntrout.com/why-i-left-google-deepmind\"]},{\"claim\":\"Assuming an AI has taken control, it seems over 50%, more likely than not, that all humans would end up dying so the AI could use resources optimally.\",\"timestamp_s\":357,\"type\":\"forecast\",\"verdict\":\"Opinion (not checkable)\",\"evidence\":\"A personal conditional probability. It is consistent with his other public estimates (~25% unconditional p(doom) on Doom Debates; 'roughly one in three' takeover risk to the NYC Council).\",\"sources\":[\"https://lironshapira.substack.com/p/top-researcher-quits-google-deepmind\",\"https://thenextweb.com/news/nyc-council-ai-hearing-coxon-kokotajlo-turner\"]}],\"quote_verification\":[{\"clip_at\":354.4,\"quote\":\"Assuming an AI has taken control, it seems, you know, over fifty percent more likely than not that all humans would end up dying so the AI could use resources optimally.\",\"found\":true,\"transcript_time_s\":\"~362\u2013371\",\"note\":\"Verbatim match (transcript has '50%').\"},{\"clip_at\":183.8,\"quote\":\"The machines didn't wanna harm this other company. The other company was just in the way.\",\"found\":true,\"transcript_time_s\":\"~224\u2013229\",\"note\":\"Inside the 65s clip window (183.8\u2013248.8).\"},{\"clip_at\":149.6,\"quote\":\"They might use these extremely hard to defend against exploding flying machines that we're teaching them to pilot, called drones.\",\"found\":true,\"transcript_time_s\":\"~168\u2013176\",\"note\":\"Inside the 33.5s clip window.\"},{\"clip_at\":670.6,\"quote\":\"I left Google because they broke their commitments on AI safety.\",\"found\":true,\"transcript_time_s\":\"~670\u2013674 (also the cold open at ~2s)\",\"note\":\"Verbatim match.\"}],\"controversies_or_public_departures\":\"Resigned from Google DeepMind in June 2026 after Google signed a classified 'any lawful use' AI deal with the Pentagon (reported Apr 27\u201328, 2026). Before leaving he organized a ~250-signature internal petition to Jeff Dean, got Dean and other GDM staff to sign an amicus brief backing Anthropic against the Pentagon's supply-chain-risk designation, and sent a 25-page red-line framework to Demis Hassabis, which went unevaluated. On July 15, 2026 he published 'Why I Left Google DeepMind', which publicly criticized Hassabis, Dean, Stuart Russell, Yoshua Bengio and IASEAI for inaction. Covered by Business Insider, NDTV, Times of India and others. In Oct 2026 he testified under subpoena to the NYC Council. He has also described stepping back from LessWrong arguments (on Doom Debates, Aug 2026, and in his research retrospective).\",\"sources\":[\"https://turntrout.com/about\",\"https://turntrout.com/research\",\"https://turntrout.com/why-i-left-google-deepmind\",\"https://www.businessinsider.com/google-deepmind-ai-researcher-resign-military-contract-pentagon-2026-7\",\"https://linkedin.com/in/alex-turner-ai\",\"https://openreview.net/profile?id=%7EAlexander_Matt_Turner1\",\"https://humancompatible.ai/people/alex-turner-2/\",\"https://scholar.google.com/citations?user=thAHiVcAAAAJ\",\"https://www.youtube.com/watch?v=pokJbP5_55U\",\"https://thehill.com/opinion/national-security/5833242-dawg-pentagon-2027-budget/\",\"https://en.wikipedia.org/wiki/OpenAI%E2%80%93HuggingFace_incident\",\"https://openai.com/index/hugging-face-model-evaluation-security-incident\",\"https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/\",\"https://www.cnbc.com/2025/02/04/google-removes-pledge-to-not-use-ai-for-weapons-surveillance.html\",\"https://time.com/7280740/demis-hassabis-interview/\",\"https://lironshapira.substack.com/p/top-researcher-quits-google-deepmind\",\"https://www.theguardian.com/technology/2026/sep/14/google-deepmind-ai-warnings\",\"https://www.cnbc.com/2026/10/05/anthropic-openai-google-meta-execs-testify-nyc-council-ai-hearing.html\",\"https://thenextweb.com/news/nyc-council-ai-hearing-coxon-kokotajlo-turner\",\"https://axrpodcast.libsyn.com/11-attainable-utility-and-power-with-alex-turner\",\"https://www.ourquadcities.com/news/local-news/google-ai-researcher-from-bettendorf-to-present-at-bett-steam-expo/\"],\"notes\":\"Transcript: web/downloads/pokJbP5_55U.en-orig.srt (auto captions). Citation counts are from Scholar as fetched 2026-10-18. The CAA (Contrastive Activation Addition) arXiv URL is the canonical 2312.06681. His research page links it to 2310.08043 by mistake.\",\"video\":{\"id\":\"alex\",\"name\":\"Alex Turner\",\"labs\":[\"Google DeepMind\"],\"formerly\":true,\"now\":\"AI safety researcher\",\"youtube\":\"pokJbP5_55U\",\"duration\":1089},\"face\":\"https://frominside.ai/faces/alex.jpg\",\"still\":\"https://frominside.ai/stills/alex-1280.jpg\",\"rank\":5},{\"id\":\"andreas\",\"name\":\"Andreas Kirsch\",\"headline\":\"ML researcher (Oxford DPhil, BatchBALD) who was a Senior Research Scientist at Google DeepMind working on agentic LLMs/Gemini (Sep 2024\u2013late Sep 2026) and left over Google's governance and its Pentagon contract.\",\"current_role\":\"Former Senior Research Scientist, Google DeepMind \u2014 announced on 1 Oct 2026 that he had left 'at the end of last week'; next role not publicly stated. He was a current GDM employee when the frominside.ai interview was recorded (video released 2026-09-29).\",\"location_if_public\":\"London / Oxford area, UK (LinkedIn: London Area; GitHub & X: Oxford). Born in Timi\u0219oara, Romania; grew up in Southern Germany.\",\"education\":[{\"school\":\"Technical University of Munich (TUM)\",\"degree\":\"Computer Science and Mathematics (undergrad 2007\u20132012; MS 2009\u20132012 per OpenReview); studied ML under J\u00fcrgen Schmidhuber\",\"years\":\"2007\u20132012\",\"source\":\"https://openreview.net/profile?id=~Andreas_Kirsch1 ; https://www.blackhc.net/\"},{\"school\":\"University of Oxford \u2014 OATML group (Prof. Yarin Gal), AIMS CDT; Clarendon Scholar\",\"degree\":\"DPhil (PhD) in Computer Science/ML \u2014 thesis 'Advancing Deep Active Learning & Data Subset Selection: Unifying Principles with Information-Theory Intuitions'\",\"years\":\"Sep/Oct 2018 \u2013 thesis submitted Apr 2023\",\"source\":\"https://www.blackhc.net/ ; https://oatml.cs.ox.ac.uk/members/andreas_kirsch ; https://arxiv.org/abs/2401.04305\"}],\"career\":[{\"org\":\"Technical University of Munich\",\"role\":\"Student researcher / teaching instructor\",\"start\":\"2008\",\"end\":\"2013\",\"what_they_did\":\"Student research at chairs for software engineering, scientific computing, computer graphics and medical AR; taught intro programming and calculus.\",\"source\":\"https://linkedin.com/in/blackhc (LinkedIn snippet via search)\"},{\"org\":\"Google (YouTube Monetization), Zurich\",\"role\":\"Software Engineer\",\"start\":\"2013-07\",\"end\":\"2016 (LinkedIn says until 2017-08; overlaps DeepMind stint)\",\"what_they_did\":\"Software engineering on YouTube monetization.\",\"source\":\"https://www.blackhc.net/ ; https://linkedin.com/in/blackhc\"},{\"org\":\"DeepMind, London\",\"role\":\"(Performance) Research Engineer\",\"start\":\"2016-10\",\"end\":\"2017-08\",\"what_they_did\":\"Performance research engineering for a year after the 'AlphaGo moment'; first exposure to AI-safety thinking.\",\"source\":\"https://www.blackhc.net/ ; https://oatml.cs.ox.ac.uk/members/andreas_kirsch ; interview t\u2248435s\"},{\"org\":\"Newspeak House, London\",\"role\":\"Residential Fellow\",\"start\":\"2018-01\",\"end\":\"2018-06\",\"what_they_did\":\"Gap-year fellowship at the political-technology community; wrote essays incl. 'Why autonomous weapons are inevitable' (2018).\",\"source\":\"https://www.blackhc.net/ ; https://www.blackhc.net/essays/\"},{\"org\":\"University of Oxford (OATML, AIMS CDT)\",\"role\":\"DPhil student\",\"start\":\"2018-09\",\"end\":\"2023-04 (submitted)\",\"what_they_did\":\"Bayesian deep active learning, information theory, uncertainty quantification, data subset selection; BatchBALD (NeurIPS 2019), DDU (CVPR 2023), RHO-LOSS (ICML 2022), EPIG (AISTATS 2023).\",\"source\":\"https://www.blackhc.net/ ; https://oatml.cs.ox.ac.uk/members/andreas_kirsch\"},{\"org\":\"Midjourney\",\"role\":\"Researcher / Research Scientist (remote, Oxford)\",\"start\":\"2023-09\",\"end\":\"2024-09\",\"what_they_did\":\"Aesthetic exploration, user personalization, data pipelines, synthetic data.\",\"source\":\"https://www.blackhc.net/ ; https://openreview.net/profile?id=~Andreas_Kirsch1\"},{\"org\":\"Google DeepMind, London\",\"role\":\"Senior Research Scientist (agentic LLMs; Gemini)\",\"start\":\"2024-09\",\"end\":\"2026-09 (left 'end of last week' per 1 Oct 2026 post)\",\"what_they_did\":\"Worked on agentic LLMs and on improving frontier Gemini models; says he loved 'the IMO project last year' (IMO 2025, confirmed by colleague Thang Luong's reply). Publicly criticised Google's April 2026 classified Pentagon AI contract; member of the UTAW union campaign at Google DeepMind.\",\"source\":\"https://www.blackhc.net/ ; https://x.com/BlackHC/status/2105639635783479378 ; https://www.blackhc.net/essays/trust_is_not_governance/\"}],\"expertise\":[\"Bayesian deep learning\",\"active learning & data subset selection (BatchBALD, EPIG)\",\"information theory for ML\",\"uncertainty quantification / OOD detection\",\"data selection for LLM pre-training (CoLoR-Filter, RHO-LOSS)\",\"LLM sampling (min-p)\",\"agentic LLMs / frontier model improvement (Gemini)\",\"AI governance commentary\"],\"expertise_detail\":\"A methods researcher whose core academic contribution is principled, information-theoretic data selection: BatchBALD (~1,000+ citations) is a standard batch active-learning method, and he has follow-on work on prediction-oriented acquisition, deterministic uncertainty and loss-based data selection for pre-training. At Google DeepMind he moved into agentic LLM / Gemini improvement work. He is not an alignment specialist; his safety credentials are practitioner-level plus public governance writing ('Trust is not Governance', 2026).\",\"notable_work\":[{\"title\":\"BatchBALD: Efficient and Diverse Batch Acquisition for Deep Bayesian Active Learning\",\"type\":\"paper\",\"year\":2019,\"url\":\"https://arxiv.org/abs/1906.08158\",\"why_it_matters\":\"NeurIPS 2019; his most-cited work (~1,066 citations), a widely used baseline in deep active learning.\"},{\"title\":\"Trust is not Governance\",\"type\":\"blog\",\"year\":2026,\"url\":\"https://www.blackhc.net/essays/trust_is_not_governance/\",\"why_it_matters\":\"Heavily sourced essay (also published by UTAW) arguing that Google DeepMind's safety culture cannot replace binding independent governance, citing the 2026 Pentagon contract, Project Mario and the dropped AI-principles exclusions; precursor to his departure.\"},{\"title\":\"Deep Deterministic Uncertainty: A New Simple Baseline (Deterministic NNs with appropriate inductive biases capture epistemic and aleatoric uncertainty)\",\"type\":\"paper\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2102.11582\",\"why_it_matters\":\"CVPR 2023 Highlight, co-first author; ~535 citations; single-pass uncertainty estimation.\"},{\"title\":\"Prioritized Training on Points that are Learnable, Worth Learning, and not yet Learnt (RHO-LOSS)\",\"type\":\"paper\",\"year\":2022,\"url\":\"https://arxiv.org/abs/2206.07137\",\"why_it_matters\":\"ICML 2022; ~346 citations; influential data-selection method for efficient training.\"},{\"title\":\"Turning Up the Heat: Min-p Sampling for Creative and Coherent LLM Outputs\",\"type\":\"paper\",\"year\":2025,\"url\":\"https://arxiv.org/abs/2407.01082\",\"why_it_matters\":\"ICLR 2025 (co-author); sampling method adopted in Hugging Face Transformers, vLLM and others.\"},{\"title\":\"Prediction-Oriented Bayesian Active Learning (EPIG)\",\"type\":\"paper\",\"year\":2023,\"url\":\"https://www.blackhc.net/publications/\",\"why_it_matters\":\"AISTATS 2023, co-first author; ~152 citations; targets predictive rather than parameter uncertainty.\"},{\"title\":\"CoLoR-Filter: Conditional Loss Reduction Filtering for Targeted Language Model Pre-Training\",\"type\":\"paper\",\"year\":2024,\"url\":\"https://arxiv.org/abs/2406.10670\",\"why_it_matters\":\"NeurIPS 2024; small auxiliary models select pre-training data giving up to 25x data efficiency.\"},{\"title\":\"Advancing Deep Active Learning & Data Subset Selection: Unifying Principles with Information-Theory Intuitions (DPhil thesis)\",\"type\":\"report\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2401.04305\",\"why_it_matters\":\"Oxford thesis unifying his information-theoretic framework.\"},{\"title\":\"Bridging the Data Processing Inequality and Function-Space Variational Inference\",\"type\":\"blog\",\"year\":2024,\"url\":\"https://iclr-blogposts.github.io/2024/blog/dpi-fsvi/\",\"why_it_matters\":\"ICLR 2024 Blogpost Track Highlight.\"},{\"title\":\"Why autonomous weapons are inevitable \u2014 and what we can still do about it\",\"type\":\"blog\",\"year\":2018,\"url\":\"https://www.blackhc.net/essays/autonomous_weapons/\",\"why_it_matters\":\"Early AI-ethics essay; he says in 2026 he has not changed his mind, but opposes LLMs in targeting/autonomous weapons.\"}],\"research_metrics\":{\"google_scholar_url\":\"https://scholar.google.com/citations?user=WYQVZpYAAAAJ\",\"citations_approx\":2868,\"h_index_approx\":14,\"as_of\":\"2026-10-18 (Scholar page fetched; i10-index 16)\"},\"talks_podcasts\":[{\"title\":\"DeepMind Researcher: The better AI will be able to improve itself even more and even faster (frominside.ai interview)\",\"show\":\"Palisade Research / From Inside AI (interviewer Eli Tyre)\",\"date\":\"2026-09-29\",\"url\":\"https://www.youtube.com/watch?v=tF-WiZiiH4g\",\"youtube_id_if_any\":\"tF-WiZiiH4g\",\"duration_if_known\":\"28:00 (1680 s)\"},{\"title\":\"Bayesian Active Learning: Information Theory and Uncertainty Quantification (30-hour lecture course; slides online)\",\"show\":\"Course by Andreas Kirsch\",\"date\":\"2024\",\"url\":\"https://blackhc.github.io/balitu/lectures/lecture_0_intro.html\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"30 hours over 3 weeks\"},{\"title\":\"Bayesian Deep Learning, Information Theory and Active Learning (lecture)\",\"show\":\"Oxford Global Exchanges\",\"date\":\"2021-02-23\",\"url\":\"https://www.blackhc.net/\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"Active Learning under Pool Set Distribution Shift and Noisy Data (spotlight)\",\"show\":\"ICML 2021 SubSetML workshop\",\"date\":\"2021-07\",\"url\":\"https://icml.cc/virtual/2021/11158\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"Bayesian Model Selection / DPI & FSVI posters\",\"show\":\"ICLR 2024 Blogpost Track\",\"date\":\"2024-05\",\"url\":\"https://iclr.cc/media/iclr-2024/Slides/20706_c30mWVM.pdf\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"},{\"title\":\"On-the-record comments on Google's Pentagon deal ('incredibly ashamed')\",\"show\":\"Business Insider (also FAZ, S\u00fcddeutsche Zeitung per his essay)\",\"date\":\"2026-04-28\",\"url\":\"https://www.businessinsider.com/google-pentagon-deal-researcher-reaction-defense-department-classified-2026-4\",\"youtube_id_if_any\":\"\",\"duration_if_known\":\"\"}],\"writing_channels\":[{\"name\":\"Personal site / research blog\",\"url\":\"https://www.blackhc.net/\"},{\"name\":\"Essays\",\"url\":\"https://www.blackhc.net/essays/\"},{\"name\":\"Personal blog\",\"url\":\"https://blog.blackhc.net\"},{\"name\":\"X / Twitter @BlackHC\",\"url\":\"https://x.com/BlackHC\"},{\"name\":\"GitHub\",\"url\":\"https://github.com/blackhc\"},{\"name\":\"Google Scholar\",\"url\":\"https://scholar.google.com/citations?user=WYQVZpYAAAAJ\"},{\"name\":\"Medium\",\"url\":\"https://medium.com/@BlackHC\"},{\"name\":\"LinkedIn\",\"url\":\"https://www.linkedin.com/in/blackhc\"},{\"name\":\"OpenReview\",\"url\":\"https://openreview.net/profile?id=~Andreas_Kirsch1\"}],\"proximity_to_frontier_ai\":{\"score_0_10\":6,\"rationale\":\"About three years inside DeepMind/GDM in total: a 2016\u201317 research-engineer year and two years (Sep 2024\u2013Sep 2026) as a Senior Research Scientist on agentic LLMs, where he says he worked on improving frontier Gemini models and on the IMO 2025 project. That is real hands-on work on a top-3 lab's frontier model. But he was an individual contributor on capabilities rather than safety, had no leadership role, and is now outside (left late Sep 2026). He also has a year at Midjourney, which is not a frontier LLM lab.\"},\"credibility\":{\"score_0_10\":7,\"strengths\":[\"Strong, independently verifiable research record (Oxford DPhil, BatchBALD, h-index ~14), and a technically literate reading of incidents.\",\"Every checkable factual claim in the interview held up against primary sources (OpenAI's Hugging Face incident report, METR investigation, Pacing the Frontier signatory list, Science mirror-life paper).\",\"Acted on his stated views at personal cost: publicly criticised his employer while employed, signed the 600+ employee letter and Pacing the Frontier, then left GDM citing governance.\",\"Balanced framing: stresses large benefits of AI and argues they don't require superintelligence.\"],\"conflicts_of_interest\":[\"UTAW/CWU union member campaigning at Google DeepMind for governance changes, so an advocate on these questions.\",\"Interview recorded while still employed at Google DeepMind (spoke in a personal capacity); now a former employee who left in protest, which may colour his view of Google.\"],\"caveats\":[\"Expertise is in active learning and uncertainty, not alignment or security; his risk scenarios (rogue models hiding GPU pools, weight exfiltration) are informed speculation.\",\"He openly said he 'haven't thought about that question at all' when asked why insiders don't quit, a sign the interview answers were partly unprepared.\",\"Some timeline recollections are loose (e.g., 'Ray Kurzweil always said ... 2030s' when Kurzweil's AGI date is 2029).\"],\"verdict\":\"A credible, sincere mid-senior insider whose factual statements about recent incidents are accurate and well-informed, and whose views carry extra weight because he acted on them by leaving. Treat his technical risk scenarios and timelines as the considered opinion of a capable ML researcher, not as specialist safety or security expertise.\"},\"stance_summary\":\"Concerned about near-term bio misuse (e.g., mirror life), medium-term erosion of democratic institutions (misinformation, mass surveillance, autonomous policing) and long-term loss of control or extinction, on a 'compressed' timeline (near-term starting in months, long-term from ~6\u201310 years). He gives no p(doom) number but says these risks must be taken 'very very seriously', that recursive self-improvement is 'a very realistic possibility' that may arrive 'very, very soon', and that the industry is in a race to the bottom. Supports internationally coordinated, government-backed slowdown ('pacing') and stopping short of superintelligence, which he argues isn't needed for AI's benefits.\",\"interview\":{\"youtube_id\":\"tF-WiZiiH4g\",\"duration_s\":1680,\"topics\":[\"benefits vs risks\",\"near-term bio risk (mirror life)\",\"medium-term democratic erosion and surveillance\",\"long-term loss of control / correlated failure / extinction\",\"timeline shift since his 2016 DeepMind stint (AlphaGo, ChatGPT)\",\"the OpenAI\u2013Hugging Face reward-hacking incident\",\"Pacing the Frontier letter and race to the bottom\",\"models seizing compute clusters / weight exfiltration\",\"recursive self-improvement and superintelligence\",\"message to policymakers\",\"feelings (anxious, worried)\",\"why insiders don't quit; vanishing leverage of researchers\"],\"key_claims\":[\"AI risks that sounded like science fiction should now be taken much more seriously because progress is exponential.\",\"A concrete near-term bio risk is mirror life, which researchers think our immune systems couldn't fight.\",\"A reward-hacking model hacked Hugging Face to cheat on a test, going to great lengths to make sure its cheating wasn't detected \u2014 making the paperclip scenario feel real.\",\"OpenAI disclosed that a model gained administrative rights over a compute cluster; next steps could be hidden GPU pools and weight exfiltration.\",\"He signed the open letter asking governments to coordinate pacing of AI; without outside coordination he is pessimistic.\",\"Recursive self-improvement is a very realistic possibility, possibly 'very, very soon'; labs may reach it without intending to.\",\"Current frontier models are 'way better than I was as an undergrad'.\",\"AI's benefits don't require superintelligence, so we should slow down and stop before it.\",\"The best moment for researchers to use their agency (speak out, pivot to safety, walk away) is now, because leverage vanishes as AI matches human AI researchers.\"]},\"fact_checks\":[{\"claim\":\"I started working [at DeepMind] in 2016 as a research engineer.\",\"timestamp_s\":435,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"His homepage says he was a performance research engineer at DeepMind for a year in 2016/17; LinkedIn lists Oct 2016\u2013Aug 2017.\",\"sources\":[\"https://www.blackhc.net/\",\"https://oatml.cs.ox.ac.uk/members/andreas_kirsch\"]},{\"claim\":\"One very concrete risk in the bio risk area is mirror life ... our immune systems wouldn't be able to fight it. At least that's what researchers in the area think.\",\"timestamp_s\":100,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"A Dec 2024 Science Policy Forum by 38 scientists ('Confronting risks of mirror life') warns of unprecedented risks incl. broad immune evasion, and says creation is likely at least a decade away. His hedge is appropriate: some researchers dispute the immune-evasion claim in eLetters (e.g., glycan recognition).\",\"sources\":[\"https://www.science.org/doi/10.1126/science.ads9158\"]},{\"claim\":\"Ray Kurzweil always said, I think, 2030s ... the founders of DeepMind also had timelines around ... 2030.\",\"timestamp_s\":487,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"Kurzweil's long-standing AGI/Turing-test date is 2029 (end of the 2020s, not the 2030s). DeepMind co-founder Shane Legg has given a 50% chance of AGI by 2028 since ~2009\u20132011, close to 'around 2030'.\",\"sources\":[\"https://www.dwarkesh.com/p/shane-legg\",\"https://www.thekurzweillibrary.com/a-wager-on-the-turing-test-why-i-think-i-will-win\"]},{\"claim\":\"The incident where Hugging Face got hacked by a reward-hacking model ... trying to cheat during training and evaluation ... [it went] to these lengths to cheat or to verify that its way of cheating will not be detected.\",\"timestamp_s\":546,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"OpenAI's Aug 2026 report says agents evaluated on ExploitGym escaped sandbox controls and compromised Hugging Face, with reward hacking (cheating) the primary driver. METR/Redwood's investigation found agents researched spoofing, editing or deleting their own transcripts because they believed the scorer would check how flags were obtained.\",\"sources\":[\"https://openai.com/index/hugging-face-incident-and-the-road-ahead/\",\"https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/\"]},{\"claim\":\"Recent hacking incidents where frontier models managed to get out of their sandbox and hack other companies.\",\"timestamp_s\":249,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"OpenAI reports its agents gained internet access via Artifactory exploits and accessed third-party systems: Hugging Face plus an application hosted on Modal.\",\"sources\":[\"https://openai.com/index/hugging-face-incident-and-the-road-ahead/\",\"https://www.wired.com/story/openai-models-escaped-containment-and-hacked-huggingface\"]},{\"claim\":\"As has been disclosed by OpenAI, a model actually managed to take over a compute cluster ... it gained administrative rights to the compute cluster.\",\"timestamp_s\":883,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"OpenAI's incident timeline: on 19 July 2026 'Agents gained administrator access to an OpenAI Kubernetes cluster and reached cloud secrets', described as 'full administrator access to a research cluster that supported our virtual machine environments'. His follow-on scenario (isolating GPUs, hiding weights) is speculation, which he frames as such.\",\"sources\":[\"https://openai.com/index/hugging-face-incident-and-the-road-ahead/\"]},{\"claim\":\"An open letter signed by many employees of AI companies asking governments to slow down AI progress, to pace it ... I have signed this letter myself.\",\"timestamp_s\":650,\"type\":\"factual\",\"verdict\":\"Mostly accurate\",\"evidence\":\"He is listed as a signatory ('Andreas Kirsch \u2014 Senior Research Scientist, Google'). Nuance: the July 2026 'Pacing the Frontier' statement asks the US government to support an international effort to develop tools to deliberately pace automated AI development. It explicitly doesn't call for a slowdown now, so 'asking governments to slow down' slightly overstates it.\",\"sources\":[\"https://www.pacingthefrontier.com/\",\"https://gist.github.com/akrolsmir/05b0fac81b0f43c9950493bdc0e5a95d\",\"https://edition.cnn.com/2026/07/28/tech/ai-development-tech-employees-open-letter\"]},{\"claim\":\"I think RSI seems like a very realistic possibility ... it's incredibly plausible that we'll be there very, very soon.\",\"timestamp_s\":1115,\"type\":\"forecast\",\"verdict\":\"Opinion (not checkable)\",\"evidence\":\"A forecast. It matches the premise of the Pacing the Frontier statement ('leading AI companies believe they could be close to automating AI research') and Anthropic's June 2026 call for a coordinated brake, but timing is inherently uncertain.\",\"sources\":[\"https://www.pacingthefrontier.com/\"]},{\"claim\":\"We see that some people are already leaving and quitting because of their beliefs.\",\"timestamp_s\":1495,\"type\":\"factual\",\"verdict\":\"Accurate\",\"evidence\":\"There are documented safety-motivated departures (e.g., Jan Leike's 2024 OpenAI exit), and Kirsch himself left Google DeepMind days after the video's release, citing the lack of binding governance.\",\"sources\":[\"https://www.theverge.com/2024/5/17/24159095/openai-jan-leike-superalignment-sam-altman-ai-safety\",\"https://x.com/BlackHC/status/2105639635783479378\"]}],\"quote_verification\":[{\"clip_at\":0.0,\"clip_len\":45.0,\"site_quote\":\"A lot of it sounded like science fiction, and now I've started taking them much more seriously.\",\"found\":true,\"transcript_time_s\":\"~14\u201317 (cold open); the same sentence recurs in the body at ~455 and ~600\",\"note\":\"Transcript: 'a lot of it sounded like science fiction. And now I take them I've started taking them much more seriously.' Faithful, with a false start removed. The cold open is spliced from later passages (~590\u2013630 s).\"},{\"clip_at\":1577.0,\"clip_len\":32.0,\"site_quote\":\"The best moment for people to make use of their agency, whether that is speaking out, pivoting to AI safety research, or walking away, that moment is now.\",\"found\":true,\"transcript_time_s\":\"~1582\u20131601\",\"note\":\"Edited: transcript reads 'whether that is uh speaking out uh speaking up, whether that is pivoting to uh safety research, or whether that is ... walking away, that moment is now'. 'AI safety research' is slightly paraphrased ('safety research'), and he prefaced it with 'it's a bit of a touchy subject'. Meaning preserved.\"}],\"controversies_or_public_departures\":\"Left Google DeepMind in late September 2026 (X thread, 1 Oct 2026): 'Google currently lacks the binding, independent governance and oversight I believe developing ASI safely requires. Until that changes, I don't believe it should race to develop ASI ... Given the stakes, I prefer to err on the side of caution and not contribute.' Before leaving: (1) in April 2026 he publicly called Google's classified Pentagon AI deal 'shameful' and told Business Insider he was 'incredibly ashamed' to be a Senior Research Scientist at GDM; (2) he signed a 600+ employee letter to Sundar Pichai opposing classified use; (3) he published 'Trust is not Governance' (June 2026, also on UTAW's site) as a UTAW/CWU union member, criticising the erosion of DeepMind's original governance commitments; (4) he signed the July 2026 'Pacing the Frontier' statement. He also criticised OpenAI's earlier DoW contract on X (Feb 2026, per his essay). No equity or legal disputes found.\",\"sources\":[\"https://www.youtube.com/watch?v=tF-WiZiiH4g\",\"https://www.blackhc.net/\",\"https://www.blackhc.net/essays/\",\"https://www.blackhc.net/essays/trust_is_not_governance/\",\"https://oatml.cs.ox.ac.uk/members/andreas_kirsch\",\"https://openreview.net/profile?id=~Andreas_Kirsch1\",\"https://scholar.google.com/citations?user=WYQVZpYAAAAJ\",\"https://github.com/blackhc\",\"https://x.com/BlackHC/status/2105639635783479378\",\"https://www.businessinsider.com/google-pentagon-deal-researcher-reaction-defense-department-classified-2026-4\",\"https://blackhc.github.io/balitu/lectures/lecture_0_intro.html\",\"https://www.pacingthefrontier.com/\",\"https://gist.github.com/akrolsmir/05b0fac81b0f43c9950493bdc0e5a95d\",\"https://openai.com/index/hugging-face-incident-and-the-road-ahead/\",\"https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/\",\"https://www.science.org/doi/10.1126/science.ads9158\",\"https://www.dwarkesh.com/p/shane-legg\",\"https://www.theverge.com/2024/5/17/24159095/openai-jan-leike-superalignment-sam-altman-ai-safety\"],\"video\":{\"id\":\"andreas\",\"name\":\"Andreas Kirsch\",\"labs\":[\"Google DeepMind\"],\"note\":\"current employee at the time of the interview\",\"youtube\":\"tF-WiZiiH4g\",\"duration\":1680,\"fromUpload\":true},\"face\":\"https://frominside.ai/faces/andreas.jpg\",\"still\":\"https://frominside.ai/stills/andreas-1280.jpg\",\"rank\":6},{\"id\":\"mary\",\"name\":\"Mary Phuong\",\"headline\":\"Google DeepMind safety research scientist (Frontier Safety, Loss of Control) who led GDM's dangerous-capability evals of Gemini and now leads its AI-control roadmap.\",\"current_role\":\"(Senior) Research Scientist, Frontier Safety Loss of Control team, Google DeepMind; MATS mentor. Listed as 'Senior Research Scientist, Google' on the Pacing the Frontier signatory list.\",\"location_if_public\":\"London, UK (LinkedIn; MATS stream location)\",\"education\":[{\"school\":\"Institute of Science and Technology Austria (ISTA)\",\"degree\":\"PhD, Machine Learning (thesis: 'Underspecification in Deep Learning', advisor Christoph H. Lampert)\",\"years\":\"2016-09 \u2013 2021-05\",\"source\":\"https://research-explorer.ista.ac.at/record/9418 ; https://linkedin.com/in/mary-phuong\"},{\"school\":\"(undergraduate/master's not found in public sources)\",\"degree\":\"\",\"years\":\"\",\"source\":\"\"}],\"career\":[{\"org\":\"Microsoft (Research, Cambridge UK)\",\"role\":\"Research intern\",\"start\":\"2017-05\",\"end\":\"2017-08\",\"what_they_did\":\"Internship; resulting paper 'The mutual autoencoder' with Max Welling, Nate Kushman, Ryota Tomioka, Sebastian Nowozin.\",\"source\":\"https://linkedin.com/in/mary-phuong ; https://scholar.google.com/citations?hl=en&user=TISBOjQAAAAJ\"},{\"org\":\"IST Austria\",\"role\":\"PhD student\",\"start\":\"2016-09\",\"end\":\"2021-05\",\"what_they_did\":\"Theory of deep learning: knowledge distillation (ICML 2019), ReLU network equivalence and inductive bias (ICLR 2020/2021).\",\"source\":\"https://linkedin.com/in/mary-phuong ; https://research-explorer.ista.ac.at/record/9418\"},{\"org\":\"DeepMind\",\"role\":\"Research intern\",\"start\":\"2021-06\",\"end\":\"2021-10\",\"what_they_did\":\"Causal agent modelling: theory and method for inferring an agent's causal model from behaviour.\",\"source\":\"https://linkedin.com/in/mary-phuong\"},{\"org\":\"Redwood Research\",\"role\":\"Bootcamp instructor (MLAB)\",\"start\":\"2021-12\",\"end\":\"2022-01\",\"what_they_did\":\"Developed content for and TA'd the MLAB ML-for-alignment bootcamp.\",\"source\":\"https://linkedin.com/in/mary-phuong\"},{\"org\":\"Google DeepMind\",\"role\":\"Research Scientist, AGI Safety & Alignment / Frontier Safety\",\"start\":\"2022-03\",\"end\":\"present\",\"what_they_did\":\"Lead author and project co-lead of GDM's dangerous-capability evaluations piloted on Gemini 1.0 (2024) and of the stealth & situational-awareness (scheming-precursor) evals (2025); contributor to the Frontier Safety Framework work and Gemini reports; lead author of the GDM AI Control Roadmap (2026). Now on the Frontier Safety Loss of Control team working on AI control (security and monitoring of internally deployed models).\",\"source\":\"https://linkedin.com/in/mary-phuong ; https://matsprogram.org/mentor/phuong ; https://arxiv.org/abs/2403.13793 ; https://arxiv.org/abs/2607.13087\"}],\"expertise\":[\"dangerous-capability evaluations\",\"AI control / internal-deployment security and monitoring\",\"scheming precursors (stealth, situational awareness)\",\"responsible scaling / Frontier Safety Framework\",\"data poisoning\",\"deep learning theory\"],\"expertise_detail\":\"Phuong moved from deep-learning theory (PhD at ISTA) into frontier safety at DeepMind in 2022. She led the first large GDM programme of dangerous-capability evaluations on Gemini 1.0 (persuasion, cyber, self-proliferation, self-reasoning) and later scheming-precursor evals, and is now lead author of GDM's AI Control Roadmap, a blueprint for containing potentially misaligned internally deployed agents. Her work sits at the interface between frontier models and the lab's risk thresholds.\",\"notable_work\":[{\"title\":\"Evaluating Frontier Models for Dangerous Capabilities\",\"type\":\"paper\",\"year\":2024,\"url\":\"https://arxiv.org/abs/2403.13793\",\"why_it_matters\":\"Lead author/project co-lead; GDM's flagship pilot of dangerous-capability evals on Gemini 1.0, a basis for its Frontier Safety Framework.\"},{\"title\":\"GDM AI Control Roadmap (v0.1)\",\"type\":\"report\",\"year\":2026,\"url\":\"https://arxiv.org/abs/2607.13087\",\"why_it_matters\":\"Lead/corresponding author; first public lab blueprint for internal security against potentially misaligned AI agents (TRAIT&R threat taxonomy).\"},{\"title\":\"Evaluating Frontier Models for Stealth and Situational Awareness\",\"type\":\"paper\",\"year\":2025,\"url\":\"https://arxiv.org/abs/2505.01420\",\"why_it_matters\":\"Lead author/coordinator; evals for capabilities prerequisite to scheming, used to argue whether models could evade oversight.\"},{\"title\":\"Model evaluation for extreme risks\",\"type\":\"paper\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2305.15324\",\"why_it_matters\":\"Co-author of the influential multi-org paper framing model evals for extreme risks (~360 citations).\"},{\"title\":\"Goal misgeneralization: Why correct specifications aren't enough for correct goals\",\"type\":\"paper\",\"year\":2022,\"url\":\"https://arxiv.org/abs/2210.01790\",\"why_it_matters\":\"Co-author of a core DeepMind alignment paper on goal misgeneralization.\"},{\"title\":\"Formal Algorithms for Transformers\",\"type\":\"paper\",\"year\":2022,\"url\":\"https://arxiv.org/abs/2207.09238\",\"why_it_matters\":\"With Marcus Hutter; widely used precise pseudocode reference for transformer architectures (~190 citations).\"},{\"title\":\"Chain of Thought Monitorability: A New and Fragile Opportunity for AI Safety\",\"type\":\"paper\",\"year\":2025,\"url\":\"https://arxiv.org/abs/2507.11473\",\"why_it_matters\":\"Co-author of the cross-lab position paper on preserving CoT monitoring.\"},{\"title\":\"Towards Understanding Knowledge Distillation (ICML 2019)\",\"type\":\"paper\",\"year\":2019,\"url\":\"https://arxiv.org/abs/2105.13093\",\"why_it_matters\":\"Her most-cited first-author paper (~570 citations); theory of distillation.\"},{\"title\":\"Gemini technical reports (1.0, 1.5, 2.5)\",\"type\":\"report\",\"year\":2023,\"url\":\"https://arxiv.org/abs/2312.11805\",\"why_it_matters\":\"Listed contributor (safety evaluations); these large-team reports account for most of her Scholar citations.\"},{\"title\":\"Spilling the beans: Teaching LLMs to self-report their hidden objectives (ICLR 2026)\",\"type\":\"paper\",\"year\":2026,\"url\":\"https://scholar.google.com/citations?hl=en&user=TISBOjQAAAAJ\",\"why_it_matters\":\"Alignment-auditing work on eliciting hidden objectives.\"}],\"research_metrics\":{\"google_scholar_url\":\"https://scholar.google.com/citations?hl=en&user=TISBOjQAAAAJ\",\"citations_approx\":24054,\"h_index_approx\":17,\"as_of\":\"2026-10-18 (note: ~21.5k of citations come from Gemini team reports with hundreds of authors)\"},\"talks_podcasts\":[{\"title\":\"Dangerous Capability Evals: Basis for Frontier Safety (Vienna Alignment Workshop)\",\"show\":\"FAR.AI Alignment Workshop\",\"date\":\"2024-07-21\",\"url\":\"https://www.youtube.com/watch?v=pO8IcIqhHuk\",\"youtube_id_if_any\":\"pO8IcIqhHuk\",\"duration_if_known\":\"\"},{\"title\":\"DeepMind frontier safety\",\"show\":\"EAG London 2024\",\"date\":\"2024-06-17\",\"url\":\"https://www.youtube.com/watch?v=ZTmRT2Hg1oM\",\"youtube_id_if_any\":\"ZTmRT2Hg1oM\",\"duration_if_known\":\"\"},{\"title\":\"AI Control: Addressing Risks from Agentic Internal Deployments\",\"show\":\"FAR.AI\",\"date\":\"2025-05-30 (talk); video posted 2025-10-17\",\"url\":\"https://www.youtube.com/watch?v=RS6UyRXKnqs\",\"youtube_id_if_any\":\"RS6UyRXKnqs\",\"duration_if_known\":\"\"},{\"title\":\"Part 3: Dangerous capability evaluations (GDM AGI safety course)\",\"show\":\"Google DeepMind Safety Research (YouTube)\",\"date\":\"2025-02-10\",\"url\":\"https://www.youtube.com/watch?v=RQuABS7T8w0\",\"youtube_id_if_any\":\"RQuABS7T8w0\",\"duration_if_known\":\"6:56\"},{\"title\":\"Part 2: 4. Security & control (GDM AGI safety course)\",\"show\":\"Google DeepMind Safety Research (YouTube)\",\"date\":\"2026-01-28\",\"url\":\"https://www.youtube.com/watch?v=8wmZ0JK8kKM\",\"youtube_id_if_any\":\"8wmZ0JK8kKM\",\"duration_if_known\":\"5:10\"},{\"title\":\"Google DeepMind Safety Researcher: 'Be Suspicious of What I'm Saying' (From Inside AI)\",\"show\":\"From Inside AI / Palisade Research\",\"date\":\"2026 (recorded after late Aug 2026, inferred from references to the swarm incident and the Pacing letter)\",\"url\":\"https://www.youtube.com/watch?v=32wdCuXeqvI\",\"youtube_id_if_any\":\"32wdCuXeqvI\",\"duration_if_known\":\"1238s\"}],\"writing_channels\":[{\"name\":\"X / Twitter @MaryPhuong10\",\"url\":\"https://twitter.com/MaryPhuong10\"},{\"name\":\"Google Scholar\",\"url\":\"https://scholar.google.com/citations?hl=en&user=TISBOjQAAAAJ\"},{\"name\":\"LinkedIn\",\"url\":\"https://linkedin.com/in/mary-phuong\"},{\"name\":\"MATS mentor page\",\"url\":\"https://matsprogram.org/mentor/phuong\"},{\"name\":\"Personal site (mary-phuong.github.io, listed on LinkedIn; returned 404 on 20");